const raw = $('Telegram_Trigger').first().json;
const cfg = $('User_Config').first().json;

let staticData = {};
try {
  staticData = $getWorkflowStaticData('global');
} catch (e) {
  staticData = {};
}
staticData.sessions = staticData.sessions || {};
staticData.history = staticData.history || [];
staticData.ledger = staticData.ledger || [];

let chatId = '';
let eventType = 'ignore';
let payload = {};

const getSession = (cid) => {
  return staticData.sessions[cid] || {};
};

const saveSession = (cid, data) => {
  staticData.sessions[cid] = data;
};

const getHistory = (cid) => {
  return (staticData.history || []).filter(h => h.chatId === cid);
};

const cleanWords = (txt) => {
  return (txt || '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(w => w.length > 3);
};

const calculateOverlap = (wordsA, wordsB) => {
  if (!wordsA.length || !wordsB.length) return 0;
  const setB = new Set(wordsB);
  const intersection = wordsA.filter(w => setB.has(w));
  return intersection.length / Math.min(wordsA.length, wordsB.length);
};

const buildResumePayload = (session) => {
  const base = { session, topic: session.topic, format: session.format };
  const draft = session.draft || session.cachedDraft;
  if ((session.step === 'draft_ready' || session.step === 'dup_found' || draft) && draft) {
    session.draft = draft;
    if (!session.chosenHook && draft) {
      session.chosenHook = draft.split('\n')[0].trim();
    }
    session.step = 'draft_ready';
    const isArticle = (session.format === 'article');
    const cardText = isArticle
      ? `📰 *LinkedIn Long Article Draft Ready:*\n\n${draft}\n\n📌 *Note:* LinkedIn API does not support publishing Articles directly. Copy this text and paste it into linkedin.com/pulse.`
      : `✍️ *LinkedIn Feed Post Ready:*\n\n${draft}\n\n👇 *Tap below to publish live or regenerate:*`;
    const replyMarkup = isArticle
      ? { inline_keyboard: [ [ { text: '🔄 Regenerate Article', callback_data: 'action:regenerate' }, { text: '❌ Cancel', callback_data: 'action:cancel' } ] ] }
      : { inline_keyboard: [ [ { text: '🚀 Publish to LinkedIn', callback_data: 'action:publish' }, { text: '🔄 Regenerate Post', callback_data: 'action:regenerate' } ], [ { text: '❌ Cancel', callback_data: 'action:cancel' } ] ] };
    return {
      eventType: 'show_draft',
      payload: { ...base, post_content: draft, draft_card_text: cardText, reply_markup: replyMarkup, chosenHook: session.chosenHook }
    };
  } else if (session.step === 'gen_body' && session.chosenHook) {
    return {
      eventType: 'gen_body',
      payload: { ...base, chosenHook: session.chosenHook }
    };
  } else if (session.step === 'gen_hooks' && session.persona && session.tone) {
    return {
      eventType: 'gen_hooks',
      payload: { ...base, persona: session.persona, tone: session.tone }
    };
  } else if (session.step === 'prompt_tone' && session.persona) {
    return {
      eventType: 'prompt_tone',
      payload: { ...base, persona: session.persona }
    };
  } else if (session.step === 'prompt_persona') {
    return {
      eventType: 'prompt_persona',
      payload: { ...base }
    };
  } else {
    return {
      eventType: session.step || 'prompt_format',
      payload: { ...base }
    };
  }
};

const makeGreeting = (session) => {
  const hasActive = !!(session && session.topic);
  let greetingText = '';
  let replyMarkup = undefined;

  if (hasActive) {
    const stepLabel = session.step === 'draft_ready' ? 'Draft Ready to Publish' : session.step === 'dup_found' ? 'Existing Draft Found' : session.step === 'gen_body' ? 'Hook Selected' : session.step === 'gen_hooks' ? 'Tone Selected' : session.step === 'prompt_tone' ? 'Persona Selected' : session.step === 'prompt_persona' ? 'Format Selected' : 'Format Selection';
    greetingText = `👋 *Hey Sam!*\n\nYou have an active draft in progress:\n📌 *Topic:* "${(session.topic || '').substring(0, 80)}..."\n📍 *Progress:* ${stepLabel}\n\n👇 *Tap below to continue, or send a new topic:*`;
    replyMarkup = {
      inline_keyboard: [
        [
          { text: '🔄 Resume Active Draft', callback_data: 'action:resume' },
          { text: '❌ Cancel & Clear', callback_data: 'action:cancel' }
        ]
      ]
    };
  } else {
    greetingText = `👋 *Hey Sam! Ready to write for LinkedIn.*\n\nSend me:\n• A topic, thought, or architecture note\n• An article, repo, or blog URL\n• Production benchmarks or metrics\n\n💡 *Commands:*\n• \`/resume\` — Continue last draft\n• \`/cancel\` — Reset active session`;
  }

  return {
    has_active_session: hasActive,
    greeting_text: greetingText,
    reply_markup: replyMarkup
  };
};

if (raw.callback_query) {
  chatId = String(raw.callback_query.message.chat.id);
  const data = raw.callback_query.data || '';
  let session = getSession(chatId);

  if (data === 'action:cancel') {
    saveSession(chatId, {});
    eventType = 'cancelled';
  } else if (data === 'action:resume') {
    if (session.topic) {
      const res = buildResumePayload(session);
      eventType = res.eventType;
      payload = res.payload;
    } else {
      eventType = 'greeting';
      payload = makeGreeting(null);
    }
  } else if (data === 'action:use_cached') {
    const draft = session.cachedDraft || session.draft || '';
    session.draft = draft;
    if (!session.chosenHook && draft) {
      session.chosenHook = draft.split('\n')[0].trim();
    }
    session.step = 'draft_ready';
    saveSession(chatId, session);
    const isArticle = (session.format === 'article');
    const cardText = isArticle
      ? `📰 *LinkedIn Long Article Draft Ready:*\n\n${draft}\n\n📌 *Note:* LinkedIn API does not support publishing Articles directly. Copy this text and paste it into linkedin.com/pulse.`
      : `✍️ *LinkedIn Feed Post Ready:*\n\n${draft}\n\n👇 *Tap below to publish live or regenerate:*`;
    const replyMarkup = isArticle
      ? { inline_keyboard: [ [ { text: '🔄 Regenerate Article', callback_data: 'action:regenerate' }, { text: '❌ Cancel', callback_data: 'action:cancel' } ] ] }
      : { inline_keyboard: [ [ { text: '🚀 Publish to LinkedIn', callback_data: 'action:publish' }, { text: '🔄 Regenerate Post', callback_data: 'action:regenerate' } ], [ { text: '❌ Cancel', callback_data: 'action:cancel' } ] ] };
    eventType = 'show_draft';
    payload = { session, topic: session.topic, format: session.format, post_content: draft, draft_card_text: cardText, reply_markup: replyMarkup, chosenHook: session.chosenHook };
  } else if (data === 'action:start_fresh') {
    session.step = 'prompt_format';
    session.draft = undefined;
    session.cachedDraft = undefined;
    saveSession(chatId, session);
    eventType = 'prompt_format';
    payload = { topic: session.topic, urls: session.urls };
  } else if (data.startsWith('fmt:')) {
    session.format = data.replace('fmt:', '');
    session.step = 'prompt_persona';
    saveSession(chatId, session);
    eventType = 'prompt_persona';
    payload = { format: session.format, topic: session.topic, session };
  } else if (data.startsWith('p:')) {
    session.persona = data.replace('p:', '');
    session.step = 'prompt_tone';
    saveSession(chatId, session);
    eventType = 'prompt_tone';
    payload = { persona: session.persona, format: session.format, session };
  } else if (data.startsWith('t:')) {
    session.tone = data.replace('t:', '');
    session.step = 'gen_hooks';
    saveSession(chatId, session);
    eventType = 'gen_hooks';
    payload = { persona: session.persona, tone: session.tone, format: session.format, session };
  } else if (data === 'h:regen') {
    eventType = 'gen_hooks';
    payload = { persona: session.persona, tone: session.tone, format: session.format, session, isRegenHooks: true };
  } else if (data.startsWith('h:')) {
    const hookIndex = parseInt(data.replace('h:', ''), 10);
    const chosenHook = (session.hooks && session.hooks[hookIndex]) ? session.hooks[hookIndex] : '';
    session.chosenHook = chosenHook;
    session.step = 'gen_body';
    saveSession(chatId, session);
    eventType = 'gen_body';
    payload = { chosenHook, format: session.format, session };
  } else if (data === 'action:publish') {
    eventType = 'publish_linkedin';
    payload = { post_content: session.draft || '', session };
  } else if (data === 'action:regenerate') {
    let hook = session.chosenHook;
    if (!hook && session.draft) {
      hook = session.draft.split('\n')[0].trim();
      session.chosenHook = hook;
    }
    eventType = 'gen_body';
    payload = { chosenHook: hook, format: session.format, topic: session.topic, session, isRegenerate: true };
  }
} else if (raw.message && raw.message.text) {
  chatId = String(raw.message.chat.id);
  const text = raw.message.text.trim();

  if (chatId === String(cfg.authorized_chat_id)) {
    const lower = text.toLowerCase();
    const greetings = new Set(['hey', 'hi', 'hello', 'yo', 'sup', '/start', '/help', 'help', 'menu']);

    if (lower === '/cancel' || lower === 'cancel') {
      saveSession(chatId, {});
      eventType = 'cancelled';
    } else if (lower === '/resume' || lower === 'resume') {
      const session = getSession(chatId);
      if (session.topic) {
        const res = buildResumePayload(session);
        eventType = res.eventType;
        payload = res.payload;
      } else {
        eventType = 'greeting';
        payload = makeGreeting(null);
      }
    } else if (greetings.has(lower) || (lower.length < 6 && !text.includes('http'))) {
      const session = getSession(chatId);
      eventType = 'greeting';
      payload = makeGreeting(session);
    } else {
      const history = getHistory(chatId);
      const currentWords = cleanWords(text);
      let duplicateMatch = null;

      for (const item of history) {
        const pastWords = cleanWords(item.topic);
        const overlap = calculateOverlap(currentWords, pastWords);
        if (overlap >= 0.60 && item.draft) {
          duplicateMatch = item;
          break;
        }
      }

      const urlRegex = /https?:\/\/[^\s]+/gi;
      const matches = text.match(urlRegex) || [];
      const session = {
        topic: text,
        urls: matches,
        format: 'post',
        updatedAt: new Date().toISOString()
      };

      if (duplicateMatch) {
        session.cachedDraft = duplicateMatch.draft;
        session.cachedTopic = duplicateMatch.topic;
        session.chosenHook = duplicateMatch.hook || (duplicateMatch.draft ? duplicateMatch.draft.split('\n')[0].trim() : '');
        saveSession(chatId, session);
        eventType = 'dup_found';
        payload = { currentTopic: text, matchedTopic: duplicateMatch.topic, draft: duplicateMatch.draft };
      } else {
        session.step = 'prompt_format';
        saveSession(chatId, session);
        eventType = 'prompt_format';
        payload = { topic: text, urls: matches };
      }
    }
  }
}

const isAuthorized = (chatId === String(cfg.authorized_chat_id));
if (!isAuthorized) eventType = 'unauthorized';

return [{
  json: {
    chat_id: chatId,
    event_type: eventType,
    telegram_bot_token: cfg.telegram_bot_token,
    openrouter_api_key: cfg.openrouter_api_key,
    openrouter_model: cfg.openrouter_model,
    linkedin_author_urn: cfg.linkedin_author_urn,
    ...payload
  }
}];

