let staticData = {};
try { staticData = $getWorkflowStaticData('global'); } catch(e) {}
staticData.sessions = staticData.sessions || {};

const item = $json;
const chatId = item.chat_id;
const session = item.session || staticData.sessions[chatId] || {};
const isRegen = item.isRegenHooks || false;

const systemPrompt = `You are an elite viral LinkedIn hook architect writing for Sam V.
Your objective is to generate EXACTLY 3 distinct, scroll-stopping hooks designed to maximize feed dwell time and click-through on the "see more" cutoff.

STRICT LENGTH CONSTRAINT:
Each hook MUST be a MAXIMUM of 1 to 2 sentences (under 30 words total). Never write multi-sentence paragraphs or run-on sentences. Keep it short, sharp, provocative, and punchy.

HOOK ANGLES:
- Hook 1 (Contrarian / Myth-Busting): Overturn a commonly accepted belief or practice with bold conviction in 1-2 sentences.
- Hook 2 (Hard Truth / Pain Point): Call out an expensive mistake or harsh operational reality in 1-2 sentences.
- Hook 3 (Benchmark / Story): High-status metric, measurable breakthrough, or battle scar in 1-2 sentences.

OUTPUT FORMAT:
Output ONLY valid JSON matching this exact schema:
{
  "hook1": "1-2 sentences (max 30 words)",
  "hook2": "1-2 sentences (max 30 words)",
  "hook3": "1-2 sentences (max 30 words)"
}
Output ONLY valid JSON. No conversational text or markdown fences outside the JSON.`;

const userPrompt = `TOPIC & CONTEXT:
${session.topic || ''}

ACTIVE PERSONA: ${session.persona || 'engineer'}
ACTIVE TONE: ${session.tone || 'informative'}
${isRegen ? '\nREGENERATION NOTE: Provide 3 completely fresh, alternative angles distinct from previous hooks.\n' : ''}
Generate the 3 short viral hooks now.`;

return [{
  json: {
    ...item,
    ai_payload: {
      model: item.openrouter_model || 'openrouter/auto',
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ],
      temperature: isRegen ? 0.95 : 0.8,
      max_tokens: 1500
    }
  }
}];

let staticData = {};
try { staticData = $getWorkflowStaticData('global'); } catch(e) {}
staticData.sessions = staticData.sessions || {};

const response = $json;
const prior = $('Prepare_Hooks_Prompt').first().json;
const chatId = prior.chat_id;
const session = staticData.sessions[chatId] || {};

if (response.error || (response.statusCode && response.statusCode >= 400)) {
  const errMsg = response.error ? (response.error.message || JSON.stringify(response.error)) : `AI Service returned status ${response.statusCode}`;
  return [{
    json: {
      chat_id: chatId,
      telegram_bot_token: prior.telegram_bot_token,
      is_error: true,
      card_text: `⚠️ *OpenRouter Error Generating Hooks:*\n\n${errMsg}\n\n👇 *Tap below to retry or cancel:*`,
      reply_markup: {
        inline_keyboard: [
          [
            { text: '🔄 Retry Hooks', callback_data: 'h:regen' },
            { text: '❌ Cancel', callback_data: 'action:cancel' }
          ]
        ]
      }
    }
  }];
}

let rawContent = '';
if (response.choices && response.choices.length > 0 && response.choices[0].message) {
  rawContent = response.choices[0].message.content || '';
}

let text = rawContent.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
text = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();

let parsed = {};
try {
  parsed = JSON.parse(text);
} catch (e) {
  const extractHook = (key) => {
    const match = text.match(new RegExp(`"${key}"\\s*:\\s*"([^"\\\\]*(?:\\.[^"\\\\]*)*)"`, 'i'));
    return match ? match[1].replace(/\\"/g, '"').replace(/\\n/g, '\n') : '';
  };
  parsed = {
    hook1: extractHook('hook1'),
    hook2: extractHook('hook2'),
    hook3: extractHook('hook3')
  };
}

const topicSnippet = (session.topic || 'this space').substring(0, 60);
const hook1 = parsed.hook1 || `Most founders and engineers are looking at ${topicSnippet} completely wrong.`;
const hook2 = parsed.hook2 || `The unvarnished reality about ${topicSnippet} that nobody discusses publicly.`;
const hook3 = parsed.hook3 || `How the latest moves in ${topicSnippet} shift the entire industry benchmark.`;

const hooks = [hook1, hook2, hook3];

if (!staticData.sessions[chatId]) staticData.sessions[chatId] = {};
staticData.sessions[chatId].hooks = hooks;

return [{
  json: {
    chat_id: chatId,
    telegram_bot_token: prior.telegram_bot_token,
    hook1: hooks[0],
    hook2: hooks[1],
    hook3: hooks[2]
  }
}];

