let staticData = {};
try { staticData = $getWorkflowStaticData('global'); } catch(e) {}
staticData.sessions = staticData.sessions || {};

const item = $json;
const chatId = item.chat_id;
const session = item.session || staticData.sessions[chatId] || {};
const chosenHook = item.chosenHook || session.chosenHook || '';
const isArticle = (session.format === 'article');

const personaMap = {
  leader: 'THE LEADER: Direct, assertive, motivational. Uses short, declarative sentences to convey authority and urgency. Action-oriented, focused on results and momentum.',
  engineer: 'THE SENIOR ENGINEER: Purely functional and instructional. Assumes high level of expertise. Economical, stripped to essentials. Omit fluff, extensive use of lists and scannable technical insights.',
  mentor: 'THE PASSIONATE MENTOR: Conversational, informal, enthusiastic. Direct address ("you") and rhetorical questions. Builds rapport through anecdotes and excitement.'
};

const toneMap = {
  compare: 'Compare & Contrast: Analytical breakdown comparing tradeoffs, architectures, or philosophies side-by-side.',
  showoff: 'Show Off: Confident and proud, spotlighting elite benchmarks, high-scale metrics, and proven achievements.',
  excited: 'Excited: High energy, visionary optimism, celebrating breakthroughs with genuine passion.',
  informative: 'Informative: Educational masterclass with clear explanations and dense insight-to-word ratio.',
  formal: 'Formal: Polished, executive, measured professional business diction.',
  friendly: 'Friendly: Warm, conversational, welcoming, and peer-to-peer.',
  condescending: 'Condescending: Provocative and witty, calling out amateur anti-patterns with unshakeable technical superiority.',
  passive: 'Passive: Understated, calm, neutral, and matter-of-fact.'
};

const activePersona = personaMap[session.persona] || personaMap.engineer;
const activeTone = toneMap[session.tone] || toneMap.informative;

let systemPrompt = '';

if (isArticle) {
  systemPrompt = `You are a sophisticated ghostwriter emulating the writing style of Sam V for a long-form LinkedIn Article.
Write an authoritative, structured article designed for the LinkedIn Pulse / Articles web editor.

ARTICLE STRUCTURE:
- Catchy Article Headline on Line 1.
- Opening introduction section starting directly with the chosen hook.
- Structured H2 sections (## Section Title) with in-depth analysis and tradeoffs.
- Scannable bullet takeaways and comparison tables where valuable.
- Strategic conclusion and call to discussion.
- Length: 600 to 900 words.
- End with 3-5 relevant hashtags.
Output ONLY the article. No conversational preamble.`;
} else {
  systemPrompt = `You are a sophisticated ghostwriter emulating the writing style of Sam V for a standard LinkedIn FEED POST.
Your output will be published directly to the LinkedIn Feed API, which strictly renders PLAIN TEXT.

STRICT FEED POST RULES:
1. NO TITLE / NO HEADLINE: Do NOT include any title, headline, or bolded subject line. Start IMMEDIATELY with the chosen hook as the very first sentence.
2. STRICT LENGTH: Exactly 3 to 4 short, punchy paragraphs (total 150 to 220 words).
3. ZERO MARKDOWN SYNTAX: Strictly FORBIDDEN to use ** (asterisks), ## (hashes), --- (horizontal rules), or triple-backtick (backtick code fences). LinkedIn feed does NOT render markdown—it prints raw symbols.
4. FEED-NATIVE FORMATTING: Use clean double line breaks between paragraphs, native emojis (🚀, 💡, 📌, 👉, ⚡), and native bullet dots (•) for scannable lists.
5. PARAGRAPH BLUEPRINT:
   • Paragraph 1: The chosen hook followed immediately by the core tension or reality.
   • Paragraph 2: The breakdown (contrasting reality, key metrics, or 2-3 bullet points using •).
   • Paragraph 3 & 4: Strategic takeaway for founders/engineers and a sharp punchline closing.
6. CONDITIONAL CODE: ZERO code blocks unless the topic is explicitly about software programming.
7. HASHTAGS: End with 3-5 relevant hashtags on the final line.
Output ONLY the clean plain-text LinkedIn post.`;
}

let userPrompt = `TOPIC & CONTEXT:
${session.topic || ''}

ACTIVE PERSONA:
${activePersona}

ACTIVE TONE:
${activeTone}

MANDATORY HOOK (Must be the very first sentence):
"${chosenHook}"
`;

if (session.urls && session.urls.length > 0) {
  userPrompt += `\nRESEARCH REFERENCE LINKS:\n${session.urls.join('\n')}\nIncorporate insights from these references.\n`;
}

userPrompt += isArticle
  ? `\nWrite the complete long-form LinkedIn article now.`
  : `\nWrite the clean 3-4 paragraph plain-text feed post now (NO title, NO ** markdown, starting directly with the hook).`;

return [{
  json: {
    ...item,
    ai_payload: {
      model: item.openrouter_model || 'openrouter/auto',
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ],
      temperature: item.isRegenerate ? 0.85 : 0.7,
      max_tokens: isArticle ? 3500 : 1500
    }
  }
}];

let staticData = {};
try { staticData = $getWorkflowStaticData('global'); } catch(e) {}
staticData.sessions = staticData.sessions || {};
staticData.history = staticData.history || [];

const response = $json;
const prior = $('Prepare_Body_Prompt').first().json;
const chatId = prior.chat_id;

if (response.error || (response.statusCode && response.statusCode >= 400)) {
  const errMsg = response.error ? (response.error.message || JSON.stringify(response.error)) : `AI Service returned status ${response.statusCode}`;
  return [{
    json: {
      chat_id: chatId,
      telegram_bot_token: prior.telegram_bot_token,
      draft_card_text: `⚠️ *OpenRouter Error Generating Draft:*\n\n${errMsg}\n\n👇 *Tap below to retry or cancel:*`,
      reply_markup: {
        inline_keyboard: [
          [
            { text: '🔄 Retry Generation', callback_data: 'action:regenerate' },
            { text: '❌ Cancel', callback_data: 'action:cancel' }
          ]
        ]
      }
    }
  }];
}

let generated = '';
if (response.choices && response.choices.length > 0 && response.choices[0].message) {
  generated = response.choices[0].message.content || '';
}

// Strip reasoning or think tags
generated = generated.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();

if (!staticData.sessions[chatId]) staticData.sessions[chatId] = {};
const session = staticData.sessions[chatId];
const isArticle = (session.format === 'article');

let cleanPost = generated;
if (!isArticle) {
  // Feed Post: Sanitize any stray markdown so LinkedIn feed renders cleanly
  cleanPost = cleanPost
    .replace(/^#+\s+.*$/gm, '')          // Remove # Headers
    .replace(/\*\*(.*?)\*\*/g, '$1')        // Strip **bold** asterisks
    .replace(/\*(.*?)\*/g, '$1')            // Strip *italic* asterisks
    .replace(/^---+$/gm, '')                // Strip --- dividers
    .replace(/```[a-z]*\n?/gi, '')          // Strip code fences
    .replace(/\n{3,}/g, '\n\n')             // Normalize multiple linebreaks
    .trim();
}

session.draft = cleanPost;
session.step = 'draft_ready';

const currentHook = session.chosenHook || (cleanPost ? cleanPost.split('\n')[0].trim() : '');
session.chosenHook = currentHook;

staticData.history.unshift({
  chatId: chatId,
  topic: session.topic || '',
  draft: cleanPost,
  hook: currentHook,
  format: session.format || 'post',
  persona: session.persona || '',
  tone: session.tone || '',
  createdAt: new Date().toISOString()
});
staticData.history = staticData.history.slice(0, 30);

let cardText = '';
let replyMarkup = {};

if (isArticle) {
  cardText = `📰 *LinkedIn Long Article Draft Ready:*\n\n${cleanPost}\n\n📌 *Note:* LinkedIn API does not support publishing Articles directly. Copy this text and paste it into linkedin.com/pulse.`;
  replyMarkup = {
    inline_keyboard: [
      [
        { text: '🔄 Regenerate Article', callback_data: 'action:regenerate' },
        { text: '❌ Cancel', callback_data: 'action:cancel' }
      ]
    ]
  };
} else {
  cardText = `✍️ *LinkedIn Feed Post Ready:*\n\n${cleanPost}\n\n👇 *Tap below to publish live or regenerate:*`;
  replyMarkup = {
    inline_keyboard: [
      [
        { text: '🚀 Publish to LinkedIn', callback_data: 'action:publish' },
        { text: '🔄 Regenerate Post', callback_data: 'action:regenerate' }
      ],
      [
        { text: '❌ Cancel', callback_data: 'action:cancel' }
      ]
    ]
  };
}

return [{
  json: {
    chat_id: chatId,
    post_content: cleanPost,
    draft_card_text: cardText,
    reply_markup: replyMarkup,
    telegram_bot_token: prior.telegram_bot_token,
    linkedin_author_urn: prior.linkedin_author_urn
  }
}];

let staticData = {};
try { staticData = $getWorkflowStaticData('global'); } catch(e) {}
staticData.sessions = staticData.sessions || {};
staticData.ledger = staticData.ledger || [];

const item = $json;
const chatId = item.chat_id;
const content = item.post_content || '';
const wordCount = content.split(/\s+/).filter(Boolean).length;
const session = item.session || staticData.sessions[chatId] || {};

const ledgerEntry = {
  timestamp: new Date().toISOString(),
  author_urn: item.linkedin_author_urn || 'urn:li:person:dH38GqfHh5',
  persona: session.persona || '',
  tone: session.tone || '',
  hook: session.chosenHook || '',
  word_count: wordCount,
  topic: session.topic || '',
  status: 'PUBLISHED'
};

staticData.ledger.unshift(ledgerEntry);
staticData.ledger = staticData.ledger.slice(0, 100);

return [{
  json: {
    ...item,
    post_content: content,
    word_count: wordCount
  }
}];

